-- Issue #1441; filename generated by Supabase CLI 2.107.0 in run 45810867527.
-- Forward reconciliation of #1243 at 8da0960bb88052d4312a13bc078c9c5e4c34e90f.
-- Preserve existing case/job/evidence and Registry authority. No chart dispatch,
-- canonical writes, source permission grant, runtime invocation or publication.
-- Historical transaction bodies retained; obsolete October ledger guard replaced
-- by current receipt-bound admission substrate and exact research broker preimage.
begin;

-- DB04: immutable leased research-pass history and unfamiliar Track intake.
set local lock_timeout='5s';
set local statement_timeout='90s';

do $wk_preflight$
begin
 if current_user <> 'postgres'
    or to_regclass('mizizi_private.cases') is null
    or to_regclass('platform_private.jobs') is null
    or to_regprocedure('public.mizizi_claim_case_research_jobs_v1(text,integer,integer)') is null
 then
  raise exception 'MIZIZI research-pass substrate or migration authority absent';
 end if;
 if to_regclass('mizizi_private.research_passes') is not null
    or to_regprocedure('public.mizizi_append_research_pass_v1(uuid,text,text,text,text)') is not null
    or to_regprocedure('public.mizizi_read_research_passes_v1(uuid,text)') is not null
    or to_regprocedure('mizizi_private.admit_unfamiliar_track_investigation_v1(uuid,uuid,text)') is not null
 then
  raise exception 'MIZIZI research-pass schema collision';
 end if;
 if has_schema_privilege('service_role','mizizi_private','USAGE')
    or has_schema_privilege('authenticated','mizizi_private','USAGE')
    or has_schema_privilege('anon','mizizi_private','USAGE')
 then
  raise exception 'MIZIZI private-schema role authority drift';
 end if;
end;
$wk_preflight$;

create table mizizi_private.research_passes (
  id bigint generated always as identity primary key,
  case_id uuid not null,
  workspace_id uuid not null,
  job_id uuid not null references platform_private.jobs(id) on delete restrict,
  ordinal integer not null check (ordinal between 1 and 10000),
  predecessor_fingerprint text,
  fingerprint text not null check (fingerprint ~ '^[a-f0-9]{64}$'),
  body_text text not null check (octet_length(body_text)<=32768),
  recorded_at timestamptz not null default now(),
  constraint mizizi_research_pass_case_fk
    foreign key(workspace_id,case_id)
    references mizizi_private.cases(workspace_id,id)
    on update restrict on delete restrict,
  constraint mizizi_research_pass_chain_shape
    check ((ordinal=1 and predecessor_fingerprint is null) or
           (ordinal>1 and predecessor_fingerprint ~ '^[a-f0-9]{64}$')),
  constraint mizizi_research_pass_order_unique unique(case_id,ordinal),
  constraint mizizi_research_pass_fingerprint_unique unique(case_id,fingerprint)
);
create index mizizi_research_pass_job_idx
 on mizizi_private.research_passes(job_id);
alter table mizizi_private.research_passes enable row level security;
alter table mizizi_private.research_passes force row level security;
revoke all on mizizi_private.research_passes from public,anon,authenticated,service_role,mizizi_executor;
revoke all on sequence mizizi_private.research_passes_id_seq from public,anon,authenticated,service_role,mizizi_executor;

create function mizizi_private.block_research_pass_mutation_v1()
returns trigger language plpgsql security invoker
set search_path=pg_catalog as $block$
begin
 raise exception 'MIZIZI research passes are immutable' using errcode='55000';
end;
$block$;
create trigger mizizi_research_pass_immutable
before update or delete on mizizi_private.research_passes
for each row execute function mizizi_private.block_research_pass_mutation_v1();
revoke all on function mizizi_private.block_research_pass_mutation_v1()
 from public,anon,authenticated,service_role,mizizi_executor;

-- The service may read a case's private pass history only while it holds
-- the actual currently leased research job belonging to that same case.
create function public.mizizi_read_research_passes_v1(
 p_job_id uuid,p_worker_id text
)
returns table (ordinal integer,body_text text,fingerprint text)
language plpgsql security definer set search_path=pg_catalog
as $read$
declare v_case_id uuid;
begin
 if coalesce(auth.role(),'')<>'service_role' then
  raise exception 'Service-role research authority required' using errcode='42501';
 end if;
 if p_job_id is null or p_worker_id is null or
    p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
 then raise exception 'Invalid leased research identity' using errcode='22023';
 end if;
 select c.id into v_case_id
  from platform_private.jobs j
  join mizizi_private.case_resource_bindings b
   on b.resource_id=j.resource_id and b.case_id=j.resource_id
  join mizizi_private.cases c
   on c.id=b.case_id and c.workspace_id=b.workspace_id
 where j.id=p_job_id
   and j.command_type='mizizi.case_research_v1'
   and j.job_type='mizizi.case_research_v1'
   and j.status='running' and j.locked_by=p_worker_id
   and j.lease_expires_at>now()
   and (j.input_payload->>'case_id')::uuid=c.id
   and (j.input_payload->>'workspace_id')::uuid=c.workspace_id
   and c.current_stage='research'
   and c.revision=(j.input_payload->>'expected_case_revision')::integer;
 if v_case_id is null then
  raise exception 'Research case/worker lease not current' using errcode='55000';
 end if;
 return query
  select p.ordinal,p.body_text,p.fingerprint
  from mizizi_private.research_passes p
  where p.case_id=v_case_id order by p.ordinal;
end;
$read$;
revoke all on function public.mizizi_read_research_passes_v1(uuid,text)
 from public,anon,authenticated,mizizi_executor;
grant execute on function public.mizizi_read_research_passes_v1(uuid,text)
 to service_role;

-- Atomically append one SHA-verified pass. JSON stays as exact UTF-8 text so
-- Postgres jsonb key reordering cannot invalidate the research fingerprint.
-- This never modifies Registry, case stage, human decisions or job status.
create function public.mizizi_append_research_pass_v1(
 p_job_id uuid,p_worker_id text,p_body_text text,
 p_fingerprint text,p_predecessor text
)
returns table (case_id uuid,ordinal integer,fingerprint text,outcome text)
language plpgsql security definer set search_path=pg_catalog
as $append$
declare
 v_case_id uuid;
 v_workspace_id uuid;
 v_body jsonb;
 v_ordinal integer;
 v_last_ordinal integer;
 v_last_fingerprint text;
 v_existing text;
begin
 if coalesce(auth.role(),'')<>'service_role' then
  raise exception 'Service-role research authority required' using errcode='42501';
 end if;
 if p_job_id is null or p_worker_id is null or
    p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$' or
    p_body_text is null or octet_length(p_body_text)>32768 or
    (p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$')
 then raise exception 'Invalid bounded research-pass request' using errcode='22023';
 end if;
 if encode(sha256(convert_to(p_body_text,'UTF8')),'hex')<>p_fingerprint
 then raise exception 'Research-pass content fingerprint mismatch' using errcode='22023';
 end if;
 begin
  v_body:=p_body_text::jsonb;
 exception when others then
  raise exception 'Invalid research-pass JSON' using errcode='22023';
 end;
 if jsonb_typeof(v_body)<>'object'
    or v_body->>'contract' is distinct from 'mizizi.adaptive_investigation.v1'
    or v_body ? 'fingerprint'
    or jsonb_typeof(v_body->'sourceReceipts')<>'array'
    or jsonb_array_length(v_body->'sourceReceipts')>30
    or jsonb_typeof(v_body->'findings')<>'array'
    or jsonb_typeof(v_body->'proposedLeads')<>'array'
    or jsonb_typeof(v_body->'decision')<>'object'
 then
  raise exception 'Invalid research-pass contract' using errcode='22023';
 end if;
 begin
  v_ordinal:=(v_body->>'ordinal')::integer;
 exception when others then
  raise exception 'Research-pass ordinal is invalid' using errcode='22023';
 end;
 if (v_ordinal is null or v_ordinal not between 1 and 10000)
    or nullif(v_body->>'question','') is null
    or (v_body->>'predecessorFingerprint') is distinct from p_predecessor
 then raise exception 'Invalid research-pass identity' using errcode='22023';
 end if;
 -- Serialize appenders on the actual case row, and verify the worker's
 -- current lease and exact case revision inside this very transaction.
 select c.id,c.workspace_id into v_case_id,v_workspace_id
 from platform_private.jobs j
 join platform_private.command_receipts cr
  on cr.id=j.command_receipt_id
   and cr.resource_id=j.resource_id and cr.command_type=j.command_type
 join mizizi_private.case_resource_bindings b
  on b.resource_id=j.resource_id and b.case_id=j.resource_id
 join mizizi_private.cases c
  on c.id=b.case_id and c.workspace_id=b.workspace_id
 where j.id=p_job_id
  and j.command_type='mizizi.case_research_v1'
  and j.job_type='mizizi.case_research_v1'
  and j.status='running' and j.locked_by=p_worker_id
  and j.lease_expires_at>now() and cr.status='accepted'
  and (j.input_payload->>'case_id')::uuid=c.id
  and (j.input_payload->>'workspace_id')::uuid=c.workspace_id
  and j.input_payload->>'operation'='read_only_research'
  and c.case_state in ('open','in_progress')
  and c.current_stage='research'
  and c.revision=(j.input_payload->>'expected_case_revision')::integer
 for update of j,c;
 if v_case_id is null then
  raise exception 'Research pass is not authorized by a current job lease' using errcode='55000';
 end if;
 if v_body->>'caseId' is distinct from v_case_id::text
    or v_body->>'workspaceId' is distinct from v_workspace_id::text
 then raise exception 'Research-pass workspace or case mismatch' using errcode='42501';
 end if;
 select p.fingerprint into v_existing
  from mizizi_private.research_passes p
 where p.case_id=v_case_id and p.ordinal=v_ordinal;
 if v_existing is not null then
  if v_existing<>p_fingerprint then
   raise exception 'Conflicting immutable pass ordinal' using errcode='55000';
  end if;
  return query select v_case_id,v_ordinal,p_fingerprint,'replayed'::text;
  return;
 end if;
 select p.ordinal,p.fingerprint into v_last_ordinal,v_last_fingerprint
 from mizizi_private.research_passes p
 where p.case_id=v_case_id order by p.ordinal desc limit 1;
 if v_ordinal<>coalesce(v_last_ordinal,0)+1
    or p_predecessor is distinct from v_last_fingerprint
 then raise exception 'Research-pass chain stale or out of order' using errcode='55000';
 end if;
 insert into mizizi_private.research_passes(
  case_id,workspace_id,job_id,ordinal,predecessor_fingerprint,fingerprint,body_text
 ) values(
  v_case_id,v_workspace_id,p_job_id,v_ordinal,p_predecessor,p_fingerprint,p_body_text
 );
 return query select v_case_id,v_ordinal,p_fingerprint,'created'::text;
end;
$append$;
revoke all on function public.mizizi_append_research_pass_v1(uuid,text,text,text,text)
 from public,anon,authenticated,mizizi_executor;
grant execute on function public.mizizi_append_research_pass_v1(uuid,text,text,text,text)
 to service_role;

-- Narrow unknown-question intake. Only the JIT MIZIZI executor can admit a
-- question about a live canonical Track. It confers no mutation/review rights.
-- New questions are not forced through the historical predetermined rule list.
create function mizizi_private.admit_unfamiliar_track_investigation_v1(
 p_workspace_id uuid,p_track_id uuid,p_question text
)
returns table(case_id uuid,workspace_id uuid,case_revision integer,outcome text)
language plpgsql security definer set search_path=pg_catalog
as $unknown$
declare
 v_workspace uuid;
 v_track public.registry_tracks%rowtype;
 v_question text;
 v_key text;
 v_fp text;
 v_case mizizi_private.cases%rowtype;
 v_outcome text:='created';
begin
 perform mizizi_private.assert_executor_v1();
 if session_user<>'mizizi_executor' then
  raise exception 'Narrow MIZIZI JIT executor required' using errcode='42501';
 end if;
 v_question:=btrim(p_question);
 if p_workspace_id is null or p_track_id is null or
    p_question is null or v_question is null or
    char_length(v_question) not between 20 and 500 or
    p_question is distinct from v_question or
    p_question ~ '[[:cntrl:]]'
 then raise exception 'Invalid bounded unfamiliar research question' using errcode='22023';
 end if;
 select w.id into strict v_workspace
 from mizizi_private.workspaces w
 where w.id=p_workspace_id and w.workspace_key='wakilisha-internal'
   and w.workspace_kind='internal' and w.status='active';
 select t.* into strict v_track from public.registry_tracks t
 where t.id=p_track_id and t.status='active' for share;
 v_key:=encode(sha256(convert_to(
  jsonb_build_array(p_track_id::text,lower(v_question))::text,'UTF8')),'hex');
 v_fp:=encode(sha256(convert_to(
  jsonb_build_array(v_track.id::text,v_track.title,v_track.isrc,
                    v_track.updated_at::text)::text,'UTF8')),'hex');
 insert into mizizi_private.cases(
  workspace_id,case_key,subject_type,subject_id,claim_family_key,claim_key,
  case_state,current_stage,epistemic_state,mutation_state,
  policy_ruleset_version,last_observation_fingerprint,
  transition_actor_key,transition_reason
 )values(
  v_workspace,'mizizi:unfamiliar:v1:'||v_key,'track',v_track.id,
  'cultural_investigation_v1','unfamiliar.'||v_key,
  'in_progress','research','unknown','not_planned',
  'mizizi.research_only.v1',v_fp,'system:mizizi',
  'New unfamiliar Track research-only question admitted from live canonical source.'
 )on conflict on constraint mizizi_cases_workspace_key_unique do nothing
 returning * into v_case;
 if v_case.id is null then
  select c.* into strict v_case from mizizi_private.cases c
  where c.workspace_id=v_workspace and c.case_key='mizizi:unfamiliar:v1:'||v_key
  for update;
  if v_case.subject_type<>'track' or v_case.subject_id<>v_track.id
     or v_case.claim_family_key<>'cultural_investigation_v1'
     or v_case.claim_key<>'unfamiliar.'||v_key
     or v_case.last_observation_fingerprint is distinct from v_fp
  then
   raise exception 'Unfamiliar research replay conflicts with original source'
    using errcode='55000';
  end if;
  v_outcome:='replayed';
 end if;
 return query select v_case.id,v_workspace,v_case.revision,v_outcome;
end;
$unknown$;
revoke all on function mizizi_private.admit_unfamiliar_track_investigation_v1(uuid,uuid,text)
 from public,anon,authenticated,service_role;
grant execute on function mizizi_private.admit_unfamiliar_track_investigation_v1(uuid,uuid,text)
 to mizizi_executor;


-- DB05: narrow JIT-only external Wikidata question intake.
set local lock_timeout='5s';
set local statement_timeout='90s';
do $preflight$
begin
 if current_user<>'postgres'
  or to_regclass('mizizi_private.cases') is null
  or to_regclass('mizizi_private.research_passes') is null
  or to_regprocedure('mizizi_private.assert_executor_v1()') is null
  or to_regprocedure('mizizi_private.admit_case_research_job_v1(uuid,uuid,integer,text,text,text,text)') is null
 then
  raise exception 'STOP_MIZIZI_SOURCE_FIRST_EXACT_BASELINE';
 end if;
 if to_regprocedure('mizizi_private.admit_external_wikidata_research_v1(uuid,text,bigint,text,text)') is not null
 then raise exception 'STOP_MIZIZI_SOURCE_FIRST_GATEWAY_COLLISION';end if;
end;
$preflight$;

-- An independently acquired original Wikidata entity revision is the
-- investigation SUBJECT, not a Registry Work or rights assertion.
-- Caller's exact payload fingerprint is reverified by the external reader;
-- SQL itself does NOT claim correctness of the Wikidata assertion.
create function mizizi_private.admit_external_wikidata_research_v1(
 p_workspace_id uuid,
 p_qid text,
 p_revision bigint,
 p_source_payload_fingerprint text,
 p_public_question text
)
returns table(case_id uuid,workspace_id uuid,case_revision integer,outcome text)
language plpgsql security definer set search_path=pg_catalog
as $gate$
declare
 v_workspace uuid;
 v_qid text;
 v_question text;
 v_key text;
 v_source_uuid uuid;
 v_case mizizi_private.cases%rowtype;
 v_outcome text:='created';
begin
 perform mizizi_private.assert_executor_v1();
 if session_user<>'mizizi_executor' then
  raise exception 'Only approved narrow JIT executor may admit unfamiliar source research'
  using errcode='42501';
 end if;
 v_qid:=btrim(p_qid);
 v_question:=btrim(p_public_question);
 if p_workspace_id is null or p_qid is null
  or p_qid is distinct from v_qid
  or v_qid !~ '^Q[1-9][0-9]{0,11}$'
  or p_revision is null or p_revision<1
  or p_source_payload_fingerprint is null
  or p_source_payload_fingerprint !~ '^[a-f0-9]{64}$'
  or p_public_question is null
  or p_public_question is distinct from v_question
  or char_length(v_question) not between 20 and 500
  or v_question ~ '[[:cntrl:]]'
 then raise exception 'Invalid original public cultural observation' using errcode='22023';end if;
 select w.id into strict v_workspace
 from mizizi_private.workspaces w
 where w.id=p_workspace_id and w.workspace_key='wakilisha-internal'
  and w.workspace_kind='internal' and w.status='active';
 -- Stable external QID proxy identity. Not a Registry Work UUID.
 v_source_uuid:=md5('wikidata:external:work:'||v_qid)::uuid;
 v_key:=encode(sha256(convert_to(
  jsonb_build_array('wikidata',v_qid,lower(v_question))::text,'UTF8'
 )),'hex');
 insert into mizizi_private.cases(
  workspace_id,case_key,subject_type,subject_id,
  claim_family_key,claim_key,case_state,current_stage,
  epistemic_state,mutation_state,policy_ruleset_version,
  last_observation_fingerprint,risk_class,
  transition_actor_key,transition_reason
 )values(
  v_workspace,'mizizi:external:v1:'||v_key,'work',v_source_uuid,
  'cultural_investigation_v1','wikidata.'||lower(v_qid)||'.'||substr(v_key,1,32),
  'in_progress','research','unknown','not_planned',
  'mizizi.wikidata_research_only.v1',p_source_payload_fingerprint,'high',
  'system:mizizi',
  'Research-only Wikidata '||v_qid||' revision '||p_revision::text||
  '; external Work observation, not a canonical Registry identity or rights claim.'
 )on conflict on constraint mizizi_cases_workspace_key_unique do nothing
 returning * into v_case;
 if v_case.id is null then
  select c.* into strict v_case from mizizi_private.cases c
  where c.workspace_id=v_workspace and c.case_key='mizizi:external:v1:'||v_key
  for update;
  if v_case.subject_type<>'work' or v_case.subject_id<>v_source_uuid
   or v_case.claim_family_key<>'cultural_investigation_v1'
   or v_case.claim_key<>'wikidata.'||lower(v_qid)||'.'||substr(v_key,1,32)
   or v_case.policy_ruleset_version<>'mizizi.wikidata_research_only.v1'
   or v_case.last_observation_fingerprint is distinct from p_source_payload_fingerprint
   or v_case.transition_reason not like
     'Research-only Wikidata '||v_qid||' revision '||p_revision::text||';%'
  then raise exception 'Unfamiliar case replay changes historical evidence identity'
    using errcode='55000';
  end if;
  v_outcome:='replayed';
 end if;
 return query select v_case.id,v_workspace,v_case.revision,v_outcome;
end;
$gate$;
revoke all on function mizizi_private.admit_external_wikidata_research_v1(uuid,text,bigint,text,text)
 from public,anon,authenticated,service_role;
grant execute on function mizizi_private.admit_external_wikidata_research_v1(uuid,text,bigint,text,text)
 to mizizi_executor;

-- DB06: raise retry budget only for newly admitted MIZIZI research jobs.
set local lock_timeout='5s';
set local statement_timeout='60s';
do $preflight$
begin
 if current_user <> 'postgres'
    or to_regprocedure('mizizi_private.admit_case_research_job_v1(uuid,uuid,integer,text,text,text,text)') is null
    or to_regclass('mizizi_private.research_passes') is null
    or to_regprocedure('public.admin_mizizi_admit_chart_candidates_v1(text,jsonb)') is null
    or to_regclass('mizizi_private.chart_candidate_subjects_v1') is null
    or to_regclass('mizizi_private.chart_candidate_positions_v1') is null
    or encode(sha256(convert_to(
       pg_get_functiondef(to_regprocedure('mizizi_private.admit_case_research_job_v1(uuid,uuid,integer,text,text,text,text)')),'UTF8')),'hex')
       <> '68db13d02ff4b8cb964bd17bb197cd19345287cee20b327aaaba6a9171532dfb'
 then raise exception 'STOP_MIZIZI_RESEARCH_RETRY_BUDGET_BASELINE_DRIFT';end if;
 if (select pg_get_constraintdef(c.oid) from pg_constraint c
     where c.conrelid='platform_private.jobs'::regclass
       and c.conname='jobs_attempt_count_check')
    not like '%max_attempts <= 25%'
 then raise exception 'STOP_MIZIZI_SHARED_JOB_CAP_NOT_25';end if;
end $preflight$;

CREATE OR REPLACE FUNCTION mizizi_private.admit_case_research_job_v1(p_case_id uuid, p_workspace_id uuid, p_expected_revision integer, p_principal_key text, p_idempotency_key text, p_request_fingerprint text, p_reason text)
 RETURNS TABLE(case_id uuid, workspace_id uuid, resource_id uuid, case_revision integer, command_receipt_id uuid, job_id uuid, job_status text, outcome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_case mizizi_private.cases%rowtype;
  v_workspace uuid;
  v_resource editorial.resources%rowtype;
  v_binding mizizi_private.case_resource_bindings%rowtype;
  v_request jsonb;
  v_fp text;
  v_receipt platform_private.command_receipts%rowtype;
  v_job platform_private.jobs%rowtype;
  v_link mizizi_private.case_receipt_links%rowtype;
  v_created boolean := false;
  v_reason text;
begin
  perform mizizi_private.assert_executor_v1();
  if session_user <> 'mizizi_executor' then
    raise exception 'Only approved MIZIZI JIT executor may admit research jobs' using errcode='42501';
  end if;
  v_reason := btrim(p_reason);
  if p_case_id is null or p_workspace_id is null
     or p_expected_revision is null or p_expected_revision < 1
     or p_principal_key is distinct from 'system:mizizi'
     or p_idempotency_key is null
     or p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     or p_request_fingerprint is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_reason is null or char_length(v_reason) < 8
     or octet_length(v_reason) > 2000
  then
    raise exception 'Invalid MIZIZI shared research command' using errcode='22023';
  end if;
  v_fp := encode(extensions.digest(convert_to(
    p_case_id::text || E'\n' || p_workspace_id::text || E'\n' ||
    p_expected_revision::text || E'\nread_only_research\n' || v_reason,
    'UTF8'), 'sha256'),'hex');
  if p_request_fingerprint <> v_fp then
    raise exception 'MIZIZI research command fingerprint mismatch' using errcode='23514';
  end if;
  select w.id into strict v_workspace from mizizi_private.workspaces w
  where w.id=p_workspace_id and w.workspace_key='wakilisha-internal'
    and w.workspace_kind='internal' and w.status='active';
  select c.* into strict v_case from mizizi_private.cases c
  where c.id=p_case_id and c.workspace_id=v_workspace for update;
  if v_case.revision <> p_expected_revision
     or v_case.case_state not in ('open','in_progress') or v_case.current_stage <> 'research'
  then
    raise exception 'MIZIZI case revision or stage not eligible for research' using errcode='55000';
  end if;
  -- Make the exact case ID an actual typed editorial Resource, not a cast.
  insert into editorial.resources(id,resource_kind,visibility,lifecycle_state)
  values (v_case.id,'mizizi_case','internal','active')
  on conflict (id) do nothing;
  select res.* into strict v_resource from editorial.resources res
  where res.id=v_case.id for update;
  if v_resource.resource_kind <> 'mizizi_case'
     or v_resource.visibility <> 'internal'
     or v_resource.lifecycle_state <> 'active' then
    raise exception 'MIZIZI case Resource ID collided with another authority' using errcode='23514';
  end if;
  insert into mizizi_private.case_resource_bindings(case_id,workspace_id,resource_id)
  values(v_case.id,v_workspace,v_case.id) on conflict on constraint case_resource_bindings_pkey do nothing;
  select b.* into strict v_binding from mizizi_private.case_resource_bindings b
  where b.case_id=v_case.id for update;
  if v_binding.workspace_id <> v_workspace or v_binding.resource_id <> v_case.id
     or v_binding.resource_kind <> 'mizizi_case' then
    raise exception 'MIZIZI case Resource binding drift' using errcode='23514';
  end if;

  v_request := jsonb_build_object(
    'case_id',v_case.id,'workspace_id',v_workspace,
    'expected_case_revision',p_expected_revision,
    'operation','read_only_research','reason',v_reason);
  insert into platform_private.command_receipts(
    command_type,resource_id,principal_key,actor_user_id,idempotency_key,
    request_fingerprint,request_payload
  ) values (
    'mizizi.case_research_v1',v_case.id,p_principal_key,null,p_idempotency_key,
    v_fp,v_request
  ) on conflict (principal_key,command_type,idempotency_key) do nothing
  returning * into v_receipt;
  if v_receipt.id is null then
    select cr.* into strict v_receipt from platform_private.command_receipts cr
    where cr.principal_key=p_principal_key and cr.command_type='mizizi.case_research_v1'
      and cr.idempotency_key=p_idempotency_key for update;
    if v_receipt.resource_id <> v_case.id
       or v_receipt.request_fingerprint <> v_fp
       or v_receipt.request_payload <> v_request then
      raise exception 'MIZIZI job idempotency key was reused for a different command' using errcode='23505';
    end if;
  else
    v_created := true;
  end if;

  insert into platform_private.jobs (
    command_receipt_id,resource_id,command_type,job_key,job_type,
    status,input_payload,max_attempts
  ) values (
    v_receipt.id,v_case.id,'mizizi.case_research_v1',
    'research:' || p_expected_revision::text,'mizizi.case_research_v1',
    'queued',v_request,25
  ) on conflict on constraint jobs_receipt_job_key do nothing returning * into v_job;
  if v_job.id is null then
    select j.* into strict v_job from platform_private.jobs j
    where j.command_receipt_id=v_receipt.id
      and j.job_key='research:' || p_expected_revision::text for update;
    if v_job.resource_id <> v_case.id
       or v_job.command_type <> 'mizizi.case_research_v1'
       or v_job.job_type <> 'mizizi.case_research_v1'
       or v_job.input_payload <> v_request then
      raise exception 'MIZIZI job replay disagrees with immutable command' using errcode='23514';
    end if;
  end if;
  if v_job.status not in ('queued','retry_wait','running','succeeded') then
    raise exception 'MIZIZI job is terminal and requires a separate reviewed retry' using errcode='55000';
  end if;
  -- Reuse DB02's immutable, existence-checked typed authority links, rather
  -- than inventing a parallel receipt table or copying private payloads.
  insert into mizizi_private.case_receipt_links (
    workspace_id,case_id,relation_type,authority_schema,authority_object_type,
    authority_id,authority_fingerprint,linked_by_actor_key,link_reason
  ) values (
    v_workspace,v_case.id,'command_receipt','platform_private','command_receipts',
    v_receipt.id,v_fp,'system:mizizi',
    'MIZIZI read-only research stage accepted by the shared platform jobs ledger.'
  ) on conflict on constraint mizizi_case_receipt_links_unique
    do nothing;
  select l.* into strict v_link from mizizi_private.case_receipt_links l
  where l.case_id=v_case.id and l.relation_type='command_receipt'
    and l.authority_schema='platform_private'
    and l.authority_object_type='command_receipts'
    and l.authority_id=v_receipt.id;
  if v_link.workspace_id <> v_workspace or v_link.authority_fingerprint <> v_fp
     or v_link.linked_by_actor_key <> 'system:mizizi' then
    raise exception 'MIZIZI command receipt link identity/fingerprint drift' using errcode='23514';
  end if;
  insert into platform_private.outbox_events (
    event_key,command_receipt_id,job_id,command_type,aggregate_id,event_type,payload
  ) values (
    'command:' || v_receipt.id::text || ':accepted',v_receipt.id,v_job.id,
    'mizizi.case_research_v1',v_case.id,'mizizi.case_research_v1.accepted',
    jsonb_build_object('case_id',v_case.id,'workspace_id',v_workspace,
      'case_revision',v_case.revision,'job_id',v_job.id,
      'command_receipt_id',v_receipt.id)
  ) on conflict (event_key) do nothing;

  return query select v_case.id,v_workspace,v_case.id,v_case.revision,
    v_receipt.id,v_job.id,v_job.status,
    case when v_created then 'created'::text else 'replayed'::text end;
end;
$function$;

do $verify$
begin
 if (select proowner::regrole::text from pg_proc
      where oid='mizizi_private.admit_case_research_job_v1(uuid,uuid,integer,text,text,text,text)'::regprocedure)
    <> 'postgres'
    or has_function_privilege('authenticated',
       'mizizi_private.admit_case_research_job_v1(uuid,uuid,integer,text,text,text,text)','EXECUTE')
    or has_function_privilege('anon',
       'mizizi_private.admit_case_research_job_v1(uuid,uuid,integer,text,text,text,text)','EXECUTE')
 then raise exception 'STOP_MIZIZI_RESEARCH_RETRY_FUNCTION_ACL_DRIFT';end if;
end $verify$;

do $research_reconciliation_acl$
begin
 if not (select relrowsecurity and relforcerowsecurity from pg_class
          where oid='mizizi_private.research_passes'::regclass)
    or has_table_privilege('service_role','mizizi_private.research_passes','SELECT')
    or has_table_privilege('authenticated','mizizi_private.research_passes','SELECT')
    or has_table_privilege('anon','mizizi_private.research_passes','INSERT')
    or has_table_privilege('mizizi_executor','mizizi_private.research_passes','INSERT')
    or not has_function_privilege('service_role','public.mizizi_read_research_passes_v1(uuid,text)','EXECUTE')
    or not has_function_privilege('service_role','public.mizizi_append_research_pass_v1(uuid,text,text,text,text)','EXECUTE')
    or has_function_privilege('authenticated','public.mizizi_read_research_passes_v1(uuid,text)','EXECUTE')
    or has_function_privilege('anon','public.mizizi_append_research_pass_v1(uuid,text,text,text,text)','EXECUTE')
    or has_function_privilege('service_role','mizizi_private.admit_external_wikidata_research_v1(uuid,text,bigint,text,text)','EXECUTE')
    or not has_function_privilege('mizizi_executor','mizizi_private.admit_external_wikidata_research_v1(uuid,text,bigint,text,text)','EXECUTE')
 then raise exception 'STOP_MIZIZI_RESEARCH_RECONCILIATION_ACL_DRIFT';end if;
end $research_reconciliation_acl$;
commit;
